BEGIN;

-- Garantiza unicidad por fecha para poder hacer UPSERT
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'uq_bolsany_fecha'
          AND conrelid = 'bolsa_ny'::regclass
    ) THEN
        ALTER TABLE bolsa_ny
        ADD CONSTRAINT uq_bolsany_fecha UNIQUE (fecha_registro);
    END IF;
END$$;

-- Inserción masiva con UPSERT por fecha_registro
ON CONFLICT (fecha_registro) DO UPDATE
SET idusuario_id = EXCLUDED.idusuario_id,
    anio = EXCLUDED.anio,
    mes = EXCLUDED.mes,
    precio_cierre = EXCLUDED.precio_cierre;

COMMIT;
